function minOperations(nums) {
  // Exhaustive search: give each element to an existing increasing group whose last value is smaller,
  // or open a new group; the state is the position plus the sorted last values of the open groups.
  const memo = new Map();
  const solve = (i, lasts) => {
    if (i === nums.length) return lasts.length;
    const key = i + '|' + lasts.join(',');
    if (memo.has(key)) return memo.get(key);
    let best = solve(i + 1, [...lasts, nums[i]].sort((a, b) => a - b));
    for (let g = 0; g < lasts.length; g++) {
      if (lasts[g] < nums[i] && (g === 0 || lasts[g] !== lasts[g - 1])) {
        const next = lasts.slice();
        next[g] = nums[i];
        best = Math.min(best, solve(i + 1, next.sort((a, b) => a - b)));
      }
    }
    memo.set(key, best);
    return best;
  };
  return solve(0, []);
}

