function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const mode = Math.floor(rand() * 3);
  if (mode === 2) {
    // A falling trend with noise produces long non-increasing chains and large answers.
    const noise = size === 'large' ? 1 + Math.floor(rand() * 400) : 1 + Math.floor(rand() * 4);
    return [Array.from({ length: n }, (_, i) => Math.min(100000, n - i + Math.floor(rand() * noise)))];
  }
  const top = mode === 0 ? (size === 'large' ? 100000 : 20) : (size === 'large' ? 40 : 4);
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
